# MAGIC %md
# MAGIC ## Declarative pipelines API

# COMMAND ----------

# ==== Declarative pipelines API ====

try:
    from pyspark import pipelines as dp
except ImportError:
    import dlt

    class _DpShim:
        @staticmethod
        def materialized_view(**options):
            # Adapt the materialized-view declaration to classic DLT by removing unsupported
            # options.
            options.pop("refresh_policy", None)
            return dlt.table(**options)

    dp = _DpShim()


def materialized_view(column_comments=None, **options):
    """Declare a materialized view and attach complete Unity Catalog column comments."""
    declare = dp.materialized_view(**options)
    if not column_comments:
        return declare

    def decorate(build):
        # Wrap the dataset builder so column descriptions are attached before Lakeflow records
        # its output schema.
        def with_column_comments():
            # Run the dataset builder and attach the supplied descriptions to its output
            # columns.
            frame = build()
            missing = sorted(set(frame.columns) - set(column_comments))
            if missing:
                raise AssertionError(
                    f"{options.get('name', build.__name__)} has uncommented columns: {missing}"
                )
            for column in frame.columns:
                frame = frame.withMetadata(column, {"comment": column_comments[column]})
            return frame

        with_column_comments.__name__ = build.__name__
        return declare(with_column_comments)

    return decorate

