# MAGIC %md
# MAGIC ## Deterministic identity helpers

# COMMAND ----------

# ==== Deterministic identity helpers ====

NULL_TOKEN = "~"


def _enc(col_or_lit):
    # Encode a key component as trimmed base64, using a distinct token for nulls so separators
    # cannot collide.
    value = col_or_lit if isinstance(col_or_lit, Column) else F.lit(col_or_lit)
    text_value = F.trim(value.cast("string"))
    return F.when(value.isNull(), F.lit(NULL_TOKEN)).otherwise(
        F.base64(text_value.cast("binary"))
    )


def stable_id(namespace, *columns):
    # Hash the namespace and encoded key components into a deterministic SHA-256 identifier.
    return F.sha2(
        F.concat_ws(":", _enc(namespace), *[_enc(column) for column in columns]),
        256,
    )

def _s3b_axis_columns(axis):
    # List the scalar coding and mapping-provenance columns expected for a form's terminology
    # axis.
    return [
        f"{axis}_source_system", f"{axis}_source_code", f"{axis}_source_display",
        f"{axis}_snomed_code", f"{axis}_snomed_display", f"{axis}_omop_concept_id",
        f"{axis}_map_method", f"{axis}_map_version", f"{axis}_map_confidence",
        f"{axis}_map_rule_id", f"{axis}_map_candidate_count", f"{axis}_target_system",
        f"{axis}_target_code", f"{axis}_target_display", f"{axis}_omop_source_concept_id",
        f"{axis}_map_cosine", f"{axis}_map_scoring_model", f"{axis}_map_status",
        f"{axis}_map_status_reason", f"{axis}_map_competing_count",
        f"{axis}_map_candidate_set_id", f"{axis}_map_component_index",
        f"{axis}_map_component_count", f"{axis}_map_rollup_levels",
    ]

def _s3b_smoking_axis(df, axis, question, answer):
    # Match a normalized smoking question and answer to the smoking lookup, retaining its
    # mapping provenance.
    key = F.sha2(F.concat_ws("|", F.lower(F.trim(F.lit(question))), F.lower(F.trim(answer))), 256)
    prefix = f"_s3b_{axis}_"
    lookup = spark.read.table(S3B_SMOKING_LOOKUP_SOURCE).select(
        F.col("source_code").alias(prefix + "key"),
        *[F.col(name).alias(prefix + name) for name in (
            "target_coding_system", "target_code", "target_display", "omop_concept_id",
            "mapping_method", "mapping_version", "legacy_confidence", "mapping_rule_id",
            "candidate_count", "mapping_cosine", "scoring_model", "mapping_status",
            "status_reason", "competing_count", "candidate_set_id", "component_index",
            "component_count", "rollup_levels",
        )],
    )
    df = df.join(F.broadcast(lookup), key == F.col(prefix + "key"), "left")
    mapped = F.col(prefix + "target_code").isNotNull()
    fields = {
        "source_system": F.lit("urn:barts:form-answer:smoking"),
        "source_code": key, "source_display": answer,
        "snomed_code": F.when(F.col(prefix + "target_coding_system") == "http://snomed.info/sct",
                              F.col(prefix + "target_code")),
        "snomed_display": F.when(F.col(prefix + "target_coding_system") == "http://snomed.info/sct",
                                 F.col(prefix + "target_display")),
        "omop_concept_id": F.col(prefix + "omop_concept_id"), "map_method": F.col(prefix + "mapping_method"),
        "map_version": F.col(prefix + "mapping_version"), "map_confidence": F.col(prefix + "legacy_confidence"),
        "map_rule_id": F.col(prefix + "mapping_rule_id"), "map_candidate_count": F.col(prefix + "candidate_count"),
        "target_system": F.col(prefix + "target_coding_system"), "target_code": F.col(prefix + "target_code"),
        "target_display": F.col(prefix + "target_display"), "omop_source_concept_id": F.lit(None).cast("bigint"),
        "map_cosine": F.col(prefix + "mapping_cosine"), "map_scoring_model": F.col(prefix + "scoring_model"),
        "map_status": F.coalesce(F.col(prefix + "mapping_status"),
                                 F.when(answer.isNotNull(), F.lit("no_candidate"))),
        "map_status_reason": F.col(prefix + "status_reason"),
        "map_competing_count": F.col(prefix + "competing_count"),
        "map_candidate_set_id": F.col(prefix + "candidate_set_id"),
        "map_component_index": F.coalesce(F.col(prefix + "component_index"), F.when(answer.isNotNull(), F.lit(1))),
        "map_component_count": F.coalesce(F.col(prefix + "component_count"), F.when(answer.isNotNull(), F.lit(1))),
        "map_rollup_levels": F.col(prefix + "rollup_levels"),
    }
    for suffix, expression in fields.items():
        df = df.withColumn(f"{axis}_{suffix}", expression)
    return df.drop(*[name for name in df.columns if name.startswith(prefix)])

def _s3b_form_axis_from_omop(df, axis, source_system, source_code, source_display, concept_id, empty_reason):
    """Validate an existing PowerForm concept and expose an explicit outcome."""
    prefix = f"_s3b_{axis}_"
    concept = (spark.read.table("3_lookup.omop.concept")
               .where("invalid_reason IS NULL")
               .select(F.col("concept_id").cast("bigint").alias(prefix + "id"),
                       F.col("concept_code").alias(prefix + "code"),
                       F.col("concept_name").alias(prefix + "display"),
                       F.col("vocabulary_id").alias(prefix + "vocabulary"),
                       F.col("standard_concept").alias(prefix + "standard")))
    df = df.join(concept, concept[prefix + "id"] == concept_id.cast("bigint"), "left")
    mapped = F.col(prefix + "standard") == "S"
    target_system = (F.when(F.col(prefix + "vocabulary") == "SNOMED", F.lit("http://snomed.info/sct"))
                     .when(F.col(prefix + "vocabulary") == "LOINC", F.lit("http://loinc.org"))
                     .when(F.col(prefix + "vocabulary") == "UCUM", F.lit("http://unitsofmeasure.org"))
                     .when(mapped, F.concat(F.lit("urn:omop:vocabulary:"), F.lower(F.col(prefix + "vocabulary")))))
    values = {
        "source_system": F.lit(source_system), "source_code": source_code.cast("string"),
        "source_display": source_display.cast("string"),
        "snomed_code": F.when(mapped & (F.col(prefix + "vocabulary") == "SNOMED"), F.col(prefix + "code")),
        "snomed_display": F.when(mapped & (F.col(prefix + "vocabulary") == "SNOMED"), F.col(prefix + "display")),
        "omop_concept_id": F.when(mapped, F.col(prefix + "id")), "map_method": F.when(mapped, F.lit("rule")),
        "map_version": F.when(mapped, F.lit("POWERFORM_S5")),
        "map_confidence": F.lit(None).cast("double"),
        "map_rule_id": F.when(mapped, F.lit("powerform:S5:validated")),
        "map_candidate_count": F.when(mapped, F.lit(1)).otherwise(F.lit(0)),
        "target_system": target_system, "target_code": F.when(mapped, F.col(prefix + "code")),
        "target_display": F.when(mapped, F.col(prefix + "display")),
        "omop_source_concept_id": F.when(
            concept_id.isNotNull() & ~F.coalesce(mapped, F.lit(False)), concept_id.cast("bigint")),
        # A11: a deterministic translation is not evidence of cosine 1.0.  Keep
        # these null until the pairwise source/target embedding pass measures it.
        "map_cosine": F.lit(None).cast("double"),
        "map_scoring_model": F.lit(None).cast("string"),
        "map_status": F.when(mapped, F.lit("mapped")).otherwise(F.lit("no_candidate")),
        "map_status_reason": F.when(~F.coalesce(mapped, F.lit(False)), F.lit(empty_reason)),
        "map_competing_count": F.when(mapped, F.lit(1)).otherwise(F.lit(0)),
        "map_candidate_set_id": F.lit(None).cast("string"),
        "map_component_index": F.lit(1), "map_component_count": F.lit(1),
        "map_rollup_levels": F.lit(None).cast("int"),
    }
    for suffix, expression in values.items():
        df = df.withColumn(f"{axis}_{suffix}", expression)
    return df.drop(*[name for name in df.columns if name.startswith(prefix)])

