# ==== Configuration validation and pipeline-safe census ====

EXPECTED_FORM_SLUGS = {
    "audit_c",
    "delirium_dementia_screening",
    "smoking_status",
    "frailty_score",
    "adult_sepsis_screening",
    "swallowing_screen",
    "must",
    "mood_rankin",
    "nih_stroke_score",
    "maternity_co_smoking",
    "poms",
    "moca",
    "waterlow",
    "infection_prevention",
    "vte_risk_assessment",
    "adult_capacity_assessment",
    "ed_anderson_pressure_risk",
    "mental_health_liaison_assessment",
    "enhanced_care_risk",
    "resuscitation_plan",
    "palliative_care_holistic_assessment",
    "maternity_vte_risk_assessment",
    "maternity_personalised_care_plan",
    "family_origin_questionnaire",
    "preoperative_assessment",
    "hars_hiv_care",
    "diabetes_in_pregnancy",
    "acute_haemodialysis_treatment",
    "sbar_escalation",
    "major_trauma_rehabilitation",
}

for _config in FORM_CONFIGS:
    _validate_config(_config)

assert len(FORM_CONFIGS) == 30, f"expected 30 form configs, found {len(FORM_CONFIGS)}"
assert len({cfg["slug"] for cfg in FORM_CONFIGS}) == len(FORM_CONFIGS), "duplicate form slug"
assert {cfg["slug"] for cfg in FORM_CONFIGS} == EXPECTED_FORM_SLUGS, (
    "FORM_CONFIGS do not match the Session 1 publication manifest"
)
_source_displays = [display for cfg in FORM_CONFIGS for display in cfg["source_displays"]]
assert len(_source_displays) == len(set(_source_displays)), "source display maps to multiple form slugs"

FORM_CONFIG_BY_SLUG = {cfg["slug"]: cfg for cfg in FORM_CONFIGS}
FORM_SLUG_BY_DISPLAY = {
    display: cfg["slug"]
    for cfg in FORM_CONFIGS
    for display in cfg["source_displays"]
}
FORM_MULTI_COLUMNS = {
    (cfg["slug"], element["column"])
    for cfg in FORM_CONFIGS
    for element in cfg["elements"]
    if element["cardinality"] == "multi"
}
FORM_CONFIG_CENSUS_ROWS = [
    (
        cfg["slug"],
        cfg["display"],
        len(cfg["source_displays"]),
        len(cfg["elements"]),
        sum(1 for element in cfg["elements"] if element["cardinality"] == "multi"),
    )
    for cfg in FORM_CONFIGS
]

FORM_CONFIG_CENSUS_COLUMN_COMMENTS = {
    "slug": "Stable instrument slug used in the clinical_form_<slug> table name.",
    "display": "Reviewed human-readable instrument description.",
    "source_displays": "Number of Millennium FORM_DESC_TXT values assigned to the instrument.",
    "elements": "Number of configured response elements published by the instrument.",
    "multi_elements": "Number of configured elements retaining every active response.",
}

@materialized_view(
    name=_n("journey_clinical._form_config_census"),
    private=True,
    comment="Internal census of the 30 reviewed PowerForm instrument configurations.",
    column_comments=FORM_CONFIG_CENSUS_COLUMN_COMMENTS,
    refresh_policy="incremental",
)
def _form_config_census():
    # Build the declared dataset: Internal census of the 30 reviewed PowerForm instrument
    # configurations.
    return spark.read.table(FORM_CONFIG_CENSUS_SOURCE).select(
        "slug",
        "display",
        "source_displays",
        "elements",
        "multi_elements",
    )

