assert set(FORM_PICKLIST_OPTIONS) <= FORM_MULTI_COLUMNS, sorted(set(FORM_PICKLIST_OPTIONS) - FORM_MULTI_COLUMNS)
for _key, _options in FORM_PICKLIST_OPTIONS.items():
    _slugs = [option["slug"] for option in _options]
    assert len(_slugs) == len(set(_slugs)), ("duplicate option slug", _key)
    assert all(option["values"] for option in _options), ("option without values", _key)


def _picklist_boolean(take, option):
    """True when any selected response is this option; False when the question was answered
    with other options only; null when the instance did not answer the question at all."""
    hit = take & _response_value("CODED").isin(*option["values"])
    return F.max(F.when(hit, F.lit(True)).otherwise(F.when(take, F.lit(False))))


def _multi_aggregations(cfg, column, kind):
    # Collect selected repeatable responses into a deterministic sequence-ordered array with
    # provenance.
    take = (
        (F.col("configured_column") == column)
        & F.coalesce(F.col("is_selected"), F.lit(False))
    )
    # One struct per selected response, in sequence order, in the production field order.
    items = F.array_sort(
        F.collect_list(
            F.when(
                take,
                F.struct(
                    F.col("sequence").alias("sequence"),
                    F.col("response_id").alias("response_id"),
                    _response_value(kind).cast("string").alias("value"),
                    F.col("response_value_text").alias("text"),
                    F.expr("try_cast(value_concept_id as bigint)").alias("concept_id"),
                    F.col("value_mapping_source").alias("mapping_source"),
                    F.col("powerform_mapping_rule_id").alias("mapping_rule_id"),
                ),
            )
        )
    )
    text_column = F.array_join(
        F.transform(items, lambda item: item["value"]),
        "|",
    ).alias(f"{column}_text")
    options = FORM_PICKLIST_OPTIONS.get((cfg["slug"], column))
    if options is None:
        # Repeating free-text, numeric or date entries: the production JSON array. to_json
        # drops null fields, exactly as the production build did.
        return [F.to_json(items).alias(column), text_column]
    return [
        *[
            _picklist_boolean(take, option).alias(f"{column}__{option['slug']}")
            for option in options
        ],
        text_column,
    ]


def _multi_value_column_comments(cfg):
    """Comments for the columns _multi_aggregations adds beyond the pipe-joined text."""
    comments = {}
    for element in cfg["elements"]:
        if element["cardinality"] != "multi":
            continue
        column = element["column"]
        match_text = "; ".join(
            f"{match['label']} [{match.get('section') or 'ANY'}]"
            for match in _element_matches(element)
        )
        options = FORM_PICKLIST_OPTIONS.get((cfg["slug"], column))
        if options is None:
            comments[column] = (
                f"JSON array of every selected {element['kind']} response for {element['label']} "
                "in sequence order (sequence, response ID, value, source text, value concept ID, "
                "mapping source, mapping rule ID); [] when the question was not answered; "
                f"matches: {match_text}"
            )
            continue
        for option in options:
            spelled = " / ".join(option["values"])
            comments[f"{column}__{option['slug']}"] = (
                f"{element['label']} option '{spelled}': true when selected, false when the "
                "question was answered with other options only, null when the question was not "
                f"answered; matches: {match_text}"
            )
    return comments


def _instrument_parent(cfg):
    # Select the base form rows whose source display belongs to the configured instrument.
    return (
        spark.read.table(_n("journey_clinical.form"))
        .where(F.col("source_display").isin(*cfg["source_displays"]))
        .select(*FORM_HOUSE_COLUMNS_V2)
    )


def _instrument_responses(slug):
    # Read configured response rows for the requested form-instrument slug.
    return spark.read.table(
        _n("journey_clinical.form_response")
    ).where(F.col("form_slug") == slug)


def _instrument_column_comments(cfg):
    # Combine common form-column descriptions with descriptions derived from each configured
    # question and match rule.
    comments = dict(FORM_HOUSE_COLUMN_COMMENTS)
    for element in cfg["elements"]:
        match_text = "; ".join(
            f"{match['label']} [{match.get('section') or 'ANY'}]"
            for match in _element_matches(element)
        )
        column = element["column"]
        kind = element["kind"]
        cardinality = element["cardinality"]
        if cardinality == "single":
            comments[column] = (
                f"{element['label']} — {kind}/single selected value; "
                f"matches: {match_text}"
            )
            comments[f"{column}_text"] = (
                f"Source response text for {element['label']}; "
                f"matches: {match_text}"
            )
            comments[f"{column}_concept_id"] = (
                f"Mapped value concept identifier for {element['label']}."
            )
            comments[f"{column}_provenance"] = (
                f"JSON mapping provenance for {element['label']}: mapping source, "
                "rule ID, ruleset version, canonical rule ID and match status, "
                "question concept ID and unit concept ID."
            )
        else:
            comments[f"{column}_text"] = (
                f"Pipe-joined selected {kind} values for {element['label']}, "
                f"ordered by sequence and response ID; matches: {match_text}"
            )
    if cfg.get("carry_pregnancy_link"):
        comments["pregnancy_id"] = (
            "Pregnancy episode linked on the source form responses."
        )
        comments["pregnancy_match_method"] = (
            "Method used to link the source form response to pregnancy."
        )
    return comments

