@materialized_view(
    name=_n("journey_clinical.form_delirium_dementia_screening"),
    comment="Delirium and dementia screening (current and legacy eras): one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments=FORM_DELIRIUM_DEMENTIA_SCREENING_COLUMN_COMMENTS,
    refresh_policy="incremental",
)
def form_delirium_dementia_screening():
    # Build the declared dataset: Delirium and dementia screening (current and legacy eras): one
    # row per form instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["delirium_dementia_screening"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("delirium_dementia_screening")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("emergency_override", "CODED"),
        *_single_aggregations("deferred_for_medical_emergency", "CODED"),
        *_single_aggregations("delirium_diagnosis", "CODED"),
        *_single_aggregations("dementia_diagnosis", "CODED"),
        *_single_aggregations("more_forgetful_last_12_months", "CODED"),
        *_single_aggregations("delirium_outcome", "CODED"),
        *_single_aggregations("four_at_alertness", "CODED"),
        *_single_aggregations("four_at_amt4", "CODED"),
        *_single_aggregations("four_at_attention", "CODED"),
        *_single_aggregations("four_at_acute_change", "CODED"),
        *_single_aggregations("four_at_outcome", "CODED"),
        *_single_aggregations("four_at_score", "NUMERIC"),
        *_single_aggregations("cognitive_function_problem", "CODED"),
        *_single_aggregations("perception_problem", "CODED"),
        *_single_aggregations("physical_function_change", "CODED"),
        *_single_aggregations("social_behaviour_change", "CODED"),
        *_single_aggregations("screening_not_appropriate_reason", "CODED"),
        *_single_aggregations("amts_outcome", "CODED"),
        *_single_aggregations("amts_age", "CODED"),
        *_single_aggregations("amts_time", "CODED"),
        *_single_aggregations("amts_year", "CODED"),
        *_single_aggregations("amts_place", "CODED"),
        *_single_aggregations("amts_date_of_birth", "CODED"),
        *_single_aggregations("amts_identify_two_people", "CODED"),
        *_single_aggregations("amts_first_world_war_year", "CODED"),
        *_single_aggregations("amts_monarch", "CODED"),
        *_single_aggregations("amts_count_backwards", "CODED"),
        *_single_aggregations("amts_address_recall", "CODED"),
        *_single_aggregations("amts_total_score", "NUMERIC"),
        *_single_aggregations("opls_referral", "CODED"),
        *_single_aggregations("cognitive_screening_test_result", "CODED"),
        *_single_aggregations("collateral_history", "CODED"),
        *_single_aggregations("referral_completed", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

