@materialized_view(
    name=_n("journey_clinical.form_adult_sepsis_screening"),
    comment="Adult sepsis screening and SBAR escalation (both form eras): one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_ADULT_SEPSIS_SCREENING_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["adult_sepsis_screening"])},
    refresh_policy="incremental",
)
def form_adult_sepsis_screening():
    # Build the declared dataset: Adult sepsis screening and SBAR escalation (both form eras):
    # one row per form instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["adult_sepsis_screening"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("adult_sepsis_screening")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("red_flag", "CODED"),
        *_single_aggregations("amber_flag", "CODED"),
        *_single_aggregations("escalate_to_job_role", "TEXT"),
        *_single_aggregations("not_for_escalation", "CODED"),
        *_single_aggregations("screening_time_of_deterioration", "DATE"),
        *_single_aggregations("escalation_time_of_deterioration", "DATE"),
        *_single_aggregations("nurse", "TEXT"),
        *_multi_aggregations(cfg, "moderate_risk_criteria", "CODED"),
        *_multi_aggregations(cfg, "high_risk_criteria", "CODED"),
        *_single_aggregations("doctor_contacted", "TEXT"),
        *_single_aggregations("escalation_required", "CODED"),
        *_single_aggregations("identify_yourself", "TEXT"),
        *_single_aggregations("role", "CODED"),
        *_single_aggregations("recommendation", "CODED"),
        *_single_aggregations("outline_concern", "TEXT"),
        *_multi_aggregations(cfg, "other_clinical_signs", "CODED"),
        *_single_aggregations("agreed_plan", "TEXT"),
        *_single_aggregations("review_timeframe", "CODED"),
        *_multi_aggregations(cfg, "interventions", "CODED"),
        *_single_aggregations("person_spoken_to", "TEXT"),
        *_single_aggregations("clinical_impression", "TEXT"),
        *_single_aggregations("additional_information", "TEXT"),
        *_single_aggregations("what_else_needed", "TEXT"),
        *_single_aggregations("not_escalating_rationale", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

