@materialized_view(
    name=_n("journey_clinical.form_mood_rankin"),
    comment="Mood screening and Modified Rankin Scale: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments=FORM_MOOD_RANKIN_COLUMN_COMMENTS,
    refresh_policy="incremental",
)
def form_mood_rankin():
    # Build the declared dataset: Mood screening and Modified Rankin Scale: one row per form
    # instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["mood_rankin"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("mood_rankin")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("patient_needs_encouragement_to_do_things", "CODED"),
        *_single_aggregations("patient_looks_sad_miserable_depressed", "CODED"),
        *_single_aggregations("patient_seems_withdrawn_lacks_interest", "CODED"),
        *_single_aggregations("patient_seems_agitated_restless_anxious", "CODED"),
        *_single_aggregations("patient_ever_cry_or_seem_weepy", "CODED"),
        *_single_aggregations("patient_lethargic_reluctant_to_mobilise", "CODED"),
        *_single_aggregations("sdss_total_score", "NUMERIC"),
        *_single_aggregations("modified_rankin_scale_assessment", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

