@materialized_view(
    name=_n("journey_clinical.form_vte_risk_assessment"),
    comment="Adult VTE risk assessment: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_VTE_RISK_ASSESSMENT_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["vte_risk_assessment"])},
    refresh_policy="incremental",
)
def form_vte_risk_assessment():
    # Build the declared dataset: Adult VTE risk assessment: one row per form instance with
    # configured questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["vte_risk_assessment"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("vte_risk_assessment")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("vte_override", "CODED"),
        *_single_aggregations("mobility_all_patients", "CODED"),
        *_single_aggregations("vte_override_reason", "CODED"),
        *_multi_aggregations(cfg, "thrombosis_risk_patient_related", "CODED"),
        *_single_aggregations("bleeding_risk_admission_related", "CODED"),
        *_multi_aggregations(cfg, "thrombosis_risk_admission_related", "CODED"),
        *_single_aggregations("bleeding_risk_patient_related", "CODED"),
        *_single_aggregations("vte_risk", "CODED"),
        *_single_aggregations("bleeding_risk", "CODED"),
        *_single_aggregations("vte_prophylaxis_calc", "NUMERIC"),
        *_single_aggregations("vte_prophylaxis_prescribed_surg_med_fcst", "CODED"),
        *_single_aggregations("zzzvte_risk_intrp_5", "CODED"),
        *_single_aggregations("zzzvte_risk_intrp_1", "CODED"),
        *_single_aggregations("zzzvte_risk_intrp_2", "CODED"),
        *_single_aggregations("zzzvte_risk_intrp_3", "CODED"),
        *_single_aggregations("zzzvte_risk_intrp_4", "CODED"),
        *_single_aggregations("vte_prophylaxis_prescribed_prescribing", "CODED"),
        *_single_aggregations("obstetric_vte_risk_total_v2", "NUMERIC"),
        *_single_aggregations("person_completing_form_vte", "TEXT"),
        *_single_aggregations("height_length_measured", "NUMERIC"),
        *_single_aggregations("maternity_vte", "CODED"),
        *_single_aggregations("obstetric_vte_risk_assessment_type", "CODED"),
        *_single_aggregations("smoker", "CODED"),
        *_single_aggregations("previous_vte", "CODED"),
        *_single_aggregations("current_systemic_infection", "CODED"),
        *_single_aggregations("gross_varicose_veins", "CODED"),
        *_single_aggregations("ohss_overian_hyperstimulation_syndrome", "CODED"),
        *_single_aggregations("family_history_of_vte", "CODED"),
        *_single_aggregations("hyperemesis", "CODED"),
        *_single_aggregations("medical_comorbidities", "CODED"),
        *_single_aggregations("vte_known_thrombophilia", "CODED"),
        *_single_aggregations("ob_vte_obesity", "CODED"),
        *_single_aggregations("patient_at_risk_of_vte", "CODED"),
        *_single_aggregations("weight_measured", "NUMERIC"),
        *_single_aggregations("body_mass_index_measured", "NUMERIC"),
        *_single_aggregations("multiple_pregnancy_twins_or_more", "CODED"),
        *_single_aggregations("age_35_parity_3", "CODED"),
        *_single_aggregations("dehydration_reduced_immobility_art_ivf", "CODED"),
        *_single_aggregations("surg_procedure_in_this_preg_or_6_weeks", "CODED"),
        *_single_aggregations("pre_eclampsia", "CODED"),
        *_single_aggregations("elective_caesarean_section", "CODED"),
        *_single_aggregations("mid_cavity_or_rotational_forceps", "CODED"),
        *_single_aggregations("caesarean_section_in_labour", "CODED"),
        *_single_aggregations("still_birth_this_pregnancy", "CODED"),
        *_single_aggregations("preterm_birth_this_pregnancy", "CODED"),
        *_single_aggregations("age_36_or_more", "CODED"),
        *_single_aggregations("paraplegia", "CODED"),
        *_single_aggregations("parity_3_or_more", "CODED"),
        *_single_aggregations("surgical_procedure_within_last_6_weeks", "CODED"),
        *_single_aggregations("dehydration_reduced_mobility_art_ivf", "CODED"),
        *_single_aggregations("pre_eclampsia_in_this_pregnancy", "CODED"),
        *_single_aggregations("telephone_number", "TEXT"),
        *_single_aggregations("vte_reason_prophylaxis_not_prescribed_prescribing", "TEXT"),
        *_single_aggregations("multiple_pregnancy", "CODED"),
        *_single_aggregations("pph_1_litre_or_more_and_or_transfusion", "CODED"),
        *_single_aggregations("prolonged_labour_over_24_hours", "CODED"),
        *_single_aggregations("pph_1_litre_or_more_or_transfusion", "CODED"),
        *_single_aggregations("labour_24_hours_or_more", "CODED"),
        *_single_aggregations("bmi", "NUMERIC"),
        *_single_aggregations("vte_reason_prophylaxis_not_prescribed_surg_med_fcst", "TEXT"),
        *_multi_aggregations(cfg, "appropriate_thrombo_for_dr_to_prescribe", "CODED"),
        *_single_aggregations("contraindication_to_lmwh_or_heparin", "CODED"),
        *_single_aggregations("system_use_vte_assessment_condition_2", "NUMERIC"),
        *_single_aggregations("vte_surgical", "CODED"),
        *_single_aggregations("system_use_vte_assessment_status", "CODED"),
        *_single_aggregations("vte_mobility", "CODED"),
        *_single_aggregations("system_use_vte_assessment_condition_1", "NUMERIC"),
        *_multi_aggregations(cfg, "vte_other_factor_s", "CODED"),
        *_single_aggregations("vte_contra_indications", "CODED"),
        *_single_aggregations("vte_consider_contra_indications", "CODED"),
        *_single_aggregations("vte_intermittent_pneumatic", "CODED"),
        *_single_aggregations("vte_verbal_information", "CODED"),
        *_single_aggregations("vte_written_information", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

