@materialized_view(
    name=_n("journey_clinical.form_resuscitation_plan"),
    comment="Resuscitation plan and consultant validation: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_RESUSCITATION_PLAN_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["resuscitation_plan"])},
    refresh_policy="incremental",
)
def form_resuscitation_plan():
    # Build the declared dataset: Resuscitation plan and consultant validation: one row per form
    # instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["resuscitation_plan"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("resuscitation_plan")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("tep_approving_senior", "TEXT"),
        *_single_aggregations("tep_patient_for_cpr", "CODED"),
        *_single_aggregations("tep_age_group", "CODED"),
        *_single_aggregations("tep_countersigning_senior", "TEXT"),
        *_single_aggregations("tep_current_venue_of_care", "CODED"),
        *_multi_aggregations(cfg, "tep_reason_s", "CODED"),
        *_single_aggregations("tep_existing_community_instruction", "CODED"),
        *_multi_aggregations(cfg, "tep_discussed_with", "CODED"),
        *_single_aggregations("capacity_assessment_calculation", "NUMERIC"),
        *_single_aggregations("impairment_disturbance_of_mind_or_brain", "CODED"),
        *_single_aggregations("capacity_assessment_outcome", "CODED"),
        *_single_aggregations("tep_review", "TEXT"),
        *_single_aggregations("tep_period_valid", "CODED"),
        *_single_aggregations("tep_details_of_discussion_s", "TEXT"),
        *_single_aggregations("tep_patient_s_priorities", "TEXT"),
        *_single_aggregations("tep_suitable_treatments_on_ward", "CODED"),
        *_single_aggregations("tep_advanced_directive_decision", "CODED"),
        *_single_aggregations("tep_proxy", "CODED"),
        *_single_aggregations("tep_mental_capacity", "CODED"),
        *_single_aggregations("tep_supporting_information", "TEXT"),
        *_single_aggregations("might_the_impairement_affect_decision", "CODED"),
        *_single_aggregations("additional_support_to_help_make_decision", "TEXT"),
        *_single_aggregations("patient_understands_decision_to_be_made", "CODED"),
        *_single_aggregations("tep_details_of_senior_review", "TEXT"),
        *_single_aggregations("tep_details_of_community_instruction", "TEXT"),
        *_multi_aggregations(cfg, "tep_suitable_treatments_in_critical_care", "CODED"),
        *_single_aggregations("tep_reason_s_for_not_discussing", "TEXT"),
        *_single_aggregations("supporting_evidence", "TEXT"),
        *_single_aggregations("patient_retains_info_to_make_decision", "CODED"),
        *_single_aggregations("tep_legal_authority_person", "TEXT"),
        *_single_aggregations("tep_legal_authority_type", "CODED"),
        *_single_aggregations("tep_discussed_with_other", "TEXT"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

