@materialized_view(
    name=_n("journey_clinical.form_palliative_care_holistic_assessment"),
    comment="Palliative care holistic assessment: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_PALLIATIVE_CARE_HOLISTIC_ASSESSMENT_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["palliative_care_holistic_assessment"])},
    refresh_policy="incremental",
)
def form_palliative_care_holistic_assessment():
    # Build the declared dataset: Palliative care holistic assessment: one row per form instance
    # with configured questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["palliative_care_holistic_assessment"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("palliative_care_holistic_assessment")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("pal_seen_by_1", "TEXT"),
        *_single_aggregations("pal_keyworker", "TEXT"),
        *_single_aggregations("pal_team", "CODED"),
        *_single_aggregations("pal_patient_location", "CODED"),
        *_single_aggregations("pal_outcome_of_visit", "CODED"),
        *_single_aggregations("pal_preferred_place_of_care", "CODED"),
        *_single_aggregations("pal_preferred_place_of_death", "CODED"),
        *_single_aggregations("pal_dnar", "CODED"),
        *_single_aggregations("pal_overall_summary", "TEXT"),
        *_multi_aggregations(cfg, "pal_advance_care_plan", "CODED"),
        *_single_aggregations("pal_team_contact_details", "CODED"),
        *_single_aggregations("pal_actions_for_palliative_care_team", "TEXT"),
        *_single_aggregations("pal_recommendations", "TEXT"),
        *_single_aggregations("pal_physical", "TEXT"),
        *_single_aggregations("pal_performance_status_phase", "CODED"),
        *_single_aggregations("pal_phase_score", "CODED"),
        *_single_aggregations("pal_performance_status_akps", "CODED"),
        *_single_aggregations("pal_akps_score", "CODED"),
        *_single_aggregations("pal_social", "TEXT"),
        *_single_aggregations("pal_psychological", "TEXT"),
        *_single_aggregations("pal_spiritual", "TEXT"),
        *_single_aggregations("pal_tep", "CODED"),
        *_multi_aggregations(cfg, "pal_relationship", "CODED"),
        *_multi_aggregations(cfg, "pal_name", "TEXT"),
        *_single_aggregations("pal_performance_status_ipos", "CODED"),
        *_single_aggregations("pal_ipos_q2_pain", "CODED"),
        *_single_aggregations("pal_ipos_q2_weak", "CODED"),
        *_single_aggregations("pal_ipos_q2_poor_appetite", "CODED"),
        *_single_aggregations("pal_ipos_q2_poor_mobility", "CODED"),
        *_single_aggregations("pal_ipos_q2_nausea", "CODED"),
        *_single_aggregations("pal_ipos_q2_shortnes_breath", "CODED"),
        *_single_aggregations("pal_ipos_q2_vomiting", "CODED"),
        *_single_aggregations("pal_ipos_q2_constipation", "CODED"),
        *_single_aggregations("pal_ipos_q2_drowsiness", "CODED"),
        *_single_aggregations("pal_ipos_q2_dry_mouth", "CODED"),
        *_single_aggregations("pal_ipos_total_score_q3_to_9", "NUMERIC"),
        *_single_aggregations("pal_ipos_q7_pat_share_feelings", "CODED"),
        *_single_aggregations("pal_ipos_q6_pat_felt_at_peace", "CODED"),
        *_single_aggregations("pal_ipos_q8_pat_had_enough_info", "CODED"),
        *_single_aggregations("pal_ipos_q4_family_worried", "CODED"),
        *_single_aggregations("pal_ipos_q3_pat_worried", "CODED"),
        *_single_aggregations("pal_ipos_q5_pat_depressed", "CODED"),
        *_single_aggregations("pal_ipos_q9_pat_problems_addressed", "CODED"),
        *_single_aggregations("pal_key_worker_contact_details", "TEXT"),
        *_single_aggregations("pal_seen_by_2", "TEXT"),
        *_single_aggregations("advance_care_plan_comments", "TEXT"),
        *_single_aggregations("pal_ipos_total_score_q1_to_3", "NUMERIC"),
        *_single_aggregations("pal_ipos_q2_other_symptoms_1", "CODED"),
        *_single_aggregations("pal_ipos_all_total_score", "NUMERIC"),
        *_single_aggregations("pal_will", "CODED"),
        *_single_aggregations("pal_ipos_q2_other_symptoms_2", "CODED"),
        *_single_aggregations("pal_ipos_q2_other_symptoms_3", "CODED"),
        *_single_aggregations("pal_ipos_q1_comment_1", "TEXT"),
        *_single_aggregations("pal_discharge_reason", "CODED"),
        *_single_aggregations("pal_ipos_q1_comment_2", "TEXT"),
        *_single_aggregations("pal_seen_by_1_contact_details", "TEXT"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

