@materialized_view(
    name=_n("journey_clinical.form_maternity_vte_risk_assessment"),
    comment="Maternity and obstetric VTE risk assessment: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_MATERNITY_VTE_RISK_ASSESSMENT_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["maternity_vte_risk_assessment"])},
    refresh_policy="incremental",
)
def form_maternity_vte_risk_assessment():
    # Build the declared dataset: Maternity and obstetric VTE risk assessment: one row per form
    # instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["maternity_vte_risk_assessment"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("maternity_vte_risk_assessment")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("age_35_parity_3", "CODED"),
        *_single_aggregations("ob_vte_obesity", "CODED"),
        *_single_aggregations("obstetric_vte_risk_assessment_type", "CODED"),
        *_single_aggregations("obstetric_vte_risk_total_v2", "NUMERIC"),
        *_single_aggregations("previous_vte", "CODED"),
        *_single_aggregations("smoker", "CODED"),
        *_single_aggregations("current_systemic_infection", "CODED"),
        *_single_aggregations("dehydration_reduced_immobility_art_ivf", "CODED"),
        *_single_aggregations("family_history_of_vte", "CODED"),
        *_single_aggregations("gross_varicose_veins", "CODED"),
        *_single_aggregations("hyperemesis", "CODED"),
        *_single_aggregations("medical_comorbidities", "CODED"),
        *_single_aggregations("ohss_overian_hyperstimulation_syndrome", "CODED"),
        *_single_aggregations("pre_eclampsia", "CODED"),
        *_single_aggregations("surg_procedure_in_this_preg_or_6_weeks", "CODED"),
        *_single_aggregations("vte_known_thrombophilia", "CODED"),
        *_single_aggregations("patient_at_risk_of_vte", "CODED"),
        *_single_aggregations("person_completing_form_vte", "TEXT"),
        *_single_aggregations("height_length_measured", "NUMERIC"),
        *_single_aggregations("weight_measured", "NUMERIC"),
        *_single_aggregations("system_use_vte_maternity_assessment_status", "CODED"),
        *_single_aggregations("maternity_vte_total_risk_score", "NUMERIC"),
        *_single_aggregations("maternity_vte_transient_risk_score", "NUMERIC"),
        *_multi_aggregations(cfg, "maternity_vte_low_trans_risk", "CODED"),
        *_single_aggregations("caesarean_section_in_labour", "CODED"),
        *_single_aggregations("elective_caesarean_section", "CODED"),
        *_single_aggregations("mid_cavity_or_rotational_forceps", "CODED"),
        *_single_aggregations("pph_1_litre_or_more_and_or_transfusion", "CODED"),
        *_single_aggregations("preterm_birth_this_pregnancy", "CODED"),
        *_single_aggregations("prolonged_labour_over_24_hours", "CODED"),
        *_single_aggregations("still_birth_this_pregnancy", "CODED"),
        *_single_aggregations("multiple_pregnancy", "CODED"),
        *_single_aggregations("telephone_number", "TEXT"),
        *_single_aggregations("maternity_vte_action_plan", "TEXT"),
        *_single_aggregations("body_mass_index_measured", "NUMERIC"),
        *_single_aggregations("bmi", "NUMERIC"),
        *_single_aggregations("multiple_pregnancy_twins_or_more", "CODED"),
        *_single_aggregations("maternity_vte_permanent_risk_score", "NUMERIC"),
        *_multi_aggregations(cfg, "appropriate_thrombo_for_dr_to_prescribe", "CODED"),
        *_multi_aggregations(cfg, "maternity_vte_low_perm_risk", "CODED"),
        *_single_aggregations("contraindication_to_lmwh_or_heparin", "CODED"),
        *_single_aggregations("heparin_type", "CODED"),
        *_single_aggregations("maternity_vte_intermediate_trans_risk", "CODED"),
        *_single_aggregations("medical_comorbidities_type", "CODED"),
        *_single_aggregations("maternity_vte_intermediate_perm_risk", "CODED"),
        *_single_aggregations("antiphospholipid_antibodies", "CODED"),
        *_single_aggregations("factorv_leiden_heterozygous", "CODED"),
        *_single_aggregations("prothrombin_gene_mutation_heterozygous", "CODED"),
        F.max(F.col("pregnancy_id")).alias("pregnancy_id"),
        F.max(F.col("pregnancy_match_method")).alias("pregnancy_match_method"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

