@materialized_view(
    name=_n("journey_clinical.form_family_origin_questionnaire"),
    comment="Family origin questionnaire: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments=FORM_FAMILY_ORIGIN_QUESTIONNAIRE_COLUMN_COMMENTS,
    refresh_policy="incremental",
)
def form_family_origin_questionnaire():
    # Build the declared dataset: Family origin questionnaire: one row per form instance with
    # configured questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["family_origin_questionnaire"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("family_origin_questionnaire")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("h_is_this_pregnancy_a_result_of_egg_donation", "CODED"),
        *_single_aggregations("h_unknown_paternal_family_origins", "CODED"),
        *_single_aggregations("h_has_the_mother_had_a_bone_marrow_transplant", "CODED"),
        *_single_aggregations("h_is_the_pregnancy_a_result_of_sperm_donation", "CODED"),
        *_single_aggregations("h_unknown_maternal_family_origins", "CODED"),
        *_single_aggregations("family_origin_m", "CODED"),
        *_single_aggregations("family_origin_f", "CODED"),
        *_single_aggregations("gestation_at_time_of_test", "CODED"),
        *_single_aggregations("foq_additional_details", "TEXT"),
        F.max(F.col("pregnancy_id")).alias("pregnancy_id"),
        F.max(F.col("pregnancy_match_method")).alias("pregnancy_match_method"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

