@materialized_view(
    name=_n("journey_clinical.form_acute_haemodialysis_treatment"),
    comment="Acute haemodialysis treatment record: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments=FORM_ACUTE_HAEMODIALYSIS_TREATMENT_COLUMN_COMMENTS,
    refresh_policy="incremental",
)
def form_acute_haemodialysis_treatment():
    # Build the declared dataset: Acute haemodialysis treatment record: one row per form
    # instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["acute_haemodialysis_treatment"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("acute_haemodialysis_treatment")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("ahtr_prescribed_fluid_removal_l", "NUMERIC"),
        *_single_aggregations("ahtr_dialysis_date", "DATE"),
        *_single_aggregations("ahtr_potassium", "CODED"),
        *_single_aggregations("ahtr_bicarbonate", "CODED"),
        *_single_aggregations("ahtr_anticoagulation", "CODED"),
        *_single_aggregations("ahtr_dialysate_temperature", "CODED"),
        *_single_aggregations("ahtr_duration_of_dialysis_hours", "NUMERIC"),
        *_single_aggregations("ahtr_calcium", "CODED"),
        *_single_aggregations("ahtr_sodium_conductivity", "CODED"),
        *_single_aggregations("ahtr_additional_instructions_prescription", "TEXT"),
        *_single_aggregations("ahtr_dialysis_machine_number", "TEXT"),
        *_single_aggregations("ahtr_dialysis_start_time", "TEXT"),
        *_single_aggregations("ahtr_dialysis_hours", "CODED"),
        *_single_aggregations("ahtr_isolate_machine", "CODED"),
        *_single_aggregations("ahtr_pulse_hr_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_blood_pressuresp_lying_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_blood_pressuredp_lying_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_type", "CODED"),
        *_single_aggregations("ahtr_dialysis_end_time", "TEXT"),
        *_single_aggregations("ahtr_temperature_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_dialysate_flow", "CODED"),
        *_single_aggregations("ahtr_dialysate_solution", "CODED"),
        *_single_aggregations("ahtr_pulse_hr_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_blood_pressuresp_lying_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_dialysis_commenced_by", "TEXT"),
        *_single_aggregations("ahtr_blood_pressuredp_lying_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_dialyser_dd", "CODED"),
        *_single_aggregations("ahtr_temperature_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_dialysis_treatment_record_documented_by", "TEXT"),
        *_single_aggregations("ahtr_recent_travel", "CODED"),
        *_single_aggregations("ahtr_litres_processed", "NUMERIC"),
        *_single_aggregations("ahtr_blood_transfusion", "CODED"),
        *_single_aggregations("ahtr_citralock_dose", "CODED"),
        *_single_aggregations("ahtr_iv_antibiotics", "CODED"),
        *_single_aggregations("ahtrsj_additional_comments", "TEXT"),
        *_single_aggregations("ahtr_dialyser", "CODED"),
        *_single_aggregations("ahtr_other_anticoagulation", "CODED"),
        *_single_aggregations("ahtr_home_dialysis_unit", "TEXT"),
        *_single_aggregations("ahtr_inhixa_dose", "CODED"),
        *_single_aggregations("ahtr_citralock_volume_a", "NUMERIC"),
        *_single_aggregations("ahtr_citralock_volume_b", "NUMERIC"),
        *_single_aggregations("ahtr_blood_results", "TEXT"),
        *_single_aggregations("ahtr_reason_why_weight_not_recorded_pd", "TEXT"),
        *_single_aggregations("ahtr_reason_why_weight_not_recorded_pod", "TEXT"),
        *_single_aggregations("ahtr_size_of_needles", "CODED"),
        *_single_aggregations("ahtr_respiration_rate_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_drug_given", "TEXT"),
        *_single_aggregations("ahtr_weight_pre_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_dialysis_session_date", "DATE"),
        *_single_aggregations("ahtr_respiration_rate_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_additional_instructions_dialysis_details", "TEXT"),
        *_single_aggregations("ahtr_weight_post_dialysis", "NUMERIC"),
        *_single_aggregations("ahtr_other_anticoagulation_other", "TEXT"),
        *_single_aggregations("bm_predialysis", "TEXT"),
        *_single_aggregations("ahtr_number_of_units", "NUMERIC"),
        *_single_aggregations("ahtr_dry_weight_kg", "NUMERIC"),
        *_single_aggregations("ahtr_total_fluid_loss", "NUMERIC"),
        *_single_aggregations("ahtr_estimated_dry_weight_kg", "NUMERIC"),
        *_single_aggregations("bm_postdialysis", "TEXT"),
        *_single_aggregations("ahtr_anticoagulation_other", "TEXT"),
        *_single_aggregations("ahtr_citralock_dose_other", "TEXT"),
        *_single_aggregations("ahtr_tinzaparin_dose_iu", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

