@materialized_view(
    name=_n("journey_clinical.form_sbar_escalation"),
    comment="SBAR escalation and response: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_SBAR_ESCALATION_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["sbar_escalation"])},
    refresh_policy="incremental",
)
def form_sbar_escalation():
    # Build the declared dataset: SBAR escalation and response: one row per form instance with
    # configured questions as columns. Residual responses are in clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["sbar_escalation"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("sbar_escalation")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("sbar_escalation_required", "CODED"),
        *_single_aggregations("sbar_identify_yourself", "TEXT"),
        *_single_aggregations("sep_time_of_deterioration", "DATE"),
        *_single_aggregations("sbar_agreed_plan", "TEXT"),
        *_single_aggregations("sbar_outline_concern", "TEXT"),
        *_single_aggregations("sbar_recommendation", "CODED"),
        *_single_aggregations("sbar_role", "CODED"),
        *_multi_aggregations(cfg, "sbar_other_clinical_signs", "CODED"),
        *_single_aggregations("sbar_agree_timeframe_for_review_by_team_ccot_art", "CODED"),
        *_multi_aggregations(cfg, "sbar_ask_what_interventions_you_can_do", "CODED"),
        *_single_aggregations("sbar_escalation_role", "CODED"),
        *_multi_aggregations(cfg, "sbar_referral_reason", "CODED"),
        *_multi_aggregations(cfg, "sbar_advice_given", "CODED"),
        *_multi_aggregations(cfg, "sbar_contact_type", "CODED"),
        *_multi_aggregations(cfg, "sbar_escalation_response", "CODED"),
        *_single_aggregations("sbar_state_your_clinical_impression", "TEXT"),
        *_single_aggregations("sbar_name_of_person_spoken_to", "TEXT"),
        *_single_aggregations("sbar_additional_information", "TEXT"),
        *_single_aggregations("sbar_agreed_timeframe", "CODED"),
        *_single_aggregations("sbar_what_else_do_you_need", "TEXT"),
        *_single_aggregations("sbar_referrer", "TEXT"),
        *_single_aggregations("sbar_rationale_for_not_escalating", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

