@materialized_view(
    name=_n("journey_clinical.form_major_trauma_rehabilitation"),
    comment="Adult major-trauma rehabilitation data: one row per form instance with configured questions as columns. Residual responses are in clinical_form_response.",
    column_comments={**FORM_MAJOR_TRAUMA_REHABILITATION_COLUMN_COMMENTS, **_multi_value_column_comments(FORM_CONFIG_BY_SLUG["major_trauma_rehabilitation"])},
    refresh_policy="incremental",
)
def form_major_trauma_rehabilitation():
    # Build the declared dataset: Adult major-trauma rehabilitation data: one row per form
    # instance with configured questions as columns. Residual responses are in
    # clinical_form_response.
    cfg = FORM_CONFIG_BY_SLUG["major_trauma_rehabilitation"]
    parent = _instrument_parent(cfg)
    responses = _instrument_responses("major_trauma_rehabilitation")
    picked = responses.groupBy("dcp_forms_activity_id").agg(
        *_single_aggregations("amtd_does_the_patient_have_rehabilitation_needs", "CODED"),
        *_multi_aggregations(cfg, "amtd_phsyical_impairment_requiring_rehab", "CODED"),
        *_single_aggregations("amtd_employment_pre_accident", "CODED"),
        *_single_aggregations("mtd_date_completed", "DATE"),
        *_single_aggregations("amtd_rehabilitation_prescription_been_developed", "CODED"),
        *_single_aggregations("amtd_rehab_prescription_discuss_patient", "CODED"),
        *_multi_aggregations(cfg, "amtd_rehab_prescription_given_to_gp", "CODED"),
        *_single_aggregations("amtd_rehab_prescription_given_next_care_provider", "CODED"),
        *_single_aggregations("mtd_summary_of_presentation", "TEXT"),
        *_single_aggregations("amtd_the_patient_s_rehab_need_assessed", "CODED"),
        *_single_aggregations("amtd_transferred_to_appropriate_facility", "CODED"),
        *_single_aggregations("mtd_rehab_prescription_summary_of_plan", "TEXT"),
        *_single_aggregations("mtd_hospital_site", "CODED"),
        *_single_aggregations("mtd_name_of_ward", "TEXT"),
        *_single_aggregations("amtd_onwards_referrals_made", "TEXT"),
        *_single_aggregations("mtd_sitetelephone_number_rlh", "CODED"),
        *_single_aggregations("mtd_your_consultant", "TEXT"),
        *_single_aggregations("mtd_ext_no", "NUMERIC"),
        *_single_aggregations("amtd_patients_actual_discharge_destination", "TEXT"),
        *_single_aggregations("amtd_community_rehabilitation", "CODED"),
        *_single_aggregations("amtd_the_patients_destination", "CODED"),
        *_single_aggregations("mtd_contact_info_for_your_local_rehab_services", "TEXT"),
        *_single_aggregations("amtd_community_rehabilitation_need", "CODED"),
        *_single_aggregations("mtd_date_transferred_discharged", "DATE"),
        *_single_aggregations("mtd_waiting_list", "NUMERIC"),
        *_multi_aggregations(cfg, "amtd_cognitive_mood_disturb_req_rehab", "CODED"),
        *_single_aggregations("mtd_referral_sent_on", "DATE"),
        *_single_aggregations("mtd_date_referral_sent_for_further_rehab", "DATE"),
        *_single_aggregations("amtd_specialist_outpatient", "CODED"),
        *_single_aggregations("amtd_specialist_outpatient_need", "CODED"),
        *_multi_aggregations(cfg, "amtd_psychosocial_issues", "CODED"),
        *_single_aggregations("amtd_specialist_inpatient", "CODED"),
        *_single_aggregations("mtd_advice_and_education", "TEXT"),
        *_single_aggregations("mtd_date_of_review_by_rehab_unit", "DATE"),
        *_single_aggregations("pmtd_what_is_the_reason_for_variance", "CODED"),
        *_single_aggregations("amtd_non_specialist_inpatient", "CODED"),
        *_single_aggregations("amtd_specialist_inpatient_need", "CODED"),
        *_single_aggregations("amtd_non_specialist_inpatient_need", "CODED"),
        *_single_aggregations("mtd_sitetelephone_number_wx", "CODED"),
    )
    return parent.join(picked, "dcp_forms_activity_id", "left")

# COMMAND ----------

# Static contract assertions: these execute while the pipeline source is loaded, without
# triggering Spark actions or imperative writes.
assert len(FORM_RESPONSE_BASE_COLUMNS) == len(set(FORM_RESPONSE_BASE_COLUMNS))
assert set(FORM_RESPONSE_BASE_COLUMNS) == set(FORM_RESPONSE_BASE_COLUMN_COMMENTS)
assert set(FORM_RESPONSE_COLUMN_COMMENTS) == (
    set(FORM_RESPONSE_BASE_COLUMNS)
    | {"selection_rank", "is_selected", "promoted_to_table", "promoted_to_row_id"}
    | {
        column
        for axis in ("question", "answer", "unit")
        for column in _s3b_axis_columns(axis)
    }
)

